constexpr /*iterator*/ operator--(int)

    requires /*cartesian-product-is-bidirectional*/<
        Const, First, Vs...>;

constexpr /*iterator*/ &operator+=(difference_type n)

    requires /*cartesian-product-is-random-access*/<
        Const, First, Vs...>;

constexpr /*iterator*/ &operator-=(difference_type n)

    requires /*cartesian-product-is-random-access*/<
        Const, First, Vs...>;

intro:
Increments or decrements the iterator.

Let current_ denote the underlying tuple of iterators and parent_ denote the underlying pointer to cartesian_product_view.

1) Equivalent to next(); return *this;

2) Equivalent to ++*this;

3) Equivalent to auto tmp = *this; ++*this; return tmp;

4) Equivalent to prev(); return *this;

5) Equivalent to auto tmp = *this; --*this; return tmp;

6) Sets the value of *this to ret, where ret is:
 if n > 0, the value of *this provided that next been called n times. Otherwise,
 if n < 0, the value of *this provided that prev been called -n times. Otherwise,
 the value of *this before the call.

The behavior is undefined if n is not in the range [ranges::distance(*this, ranges::begin(*parent_)), ranges::distance(*this, ranges::end(*parent_))).

7) Equivalent to *this += -n; return *this;.

examples.code:
#include <ranges>
#include <iterator>
#include <functional>
#include <utility>
#include <cassert>
#include <iostream>

int main() {
    int values[]{3, 5, 7, 9};
    [[maybe_unused]] int nested[][2]{{1, 2}, {3, 4}};
    [[maybe_unused]] std::pair<int, int> pairs[]{{1, 10}, {2, 20}, {3, 30}};
    auto view = std::ranges::cartesian_product_view{values, values};
    auto position = view.begin();
    auto finish = view.end();
    assert(position != finish);
    (void)*position;
    auto copy = position;
    assert(copy == position);
    ++position;
    assert(position != copy);
    --position;
    assert(position == copy);
    position += 1;
    position -= 1;
    assert(position - copy == 0);
    assert(copy + 1 > copy);
    assert(1 + copy == copy + 1);
    (void)position[0];
    (void)std::ranges::iter_move(copy);

    assert(std::ranges::distance(view) > 0);
    std::cout << "Checks passed\n";
}
